<?php get_header(); ?><main id="main-content" class="container page-wrap"><header class="page-heading"><span class="eyebrow"><?php esc_html_e('JAVTEEN JOURNAL','javteen'); ?></span><h1><?php esc_html_e('Latest posts','javteen'); ?></h1></header><?php if(have_posts()): ?><div class="post-list"><?php while(have_posts()):the_post(); ?><article <?php post_class('post-row'); ?>><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p class="meta"><?php echo esc_html(get_the_date()); ?></p><div><?php the_excerpt(); ?></div></article><?php endwhile; ?></div><?php the_posts_pagination(); else: ?><p><?php esc_html_e('Nothing found yet.','javteen'); ?></p><?php endif; ?></main><?php get_footer(); ?>